int feedback_regression(const wchar_t*dir){FeedbackStore a,b;feedback_test_checks=feedback_test_failures=0;feedback_check(feedback_open(&a,dir),"feedback isolated store opens");if(!a.data)return 1;feedback_check(!feedback_open(&b,dir),"another process cannot overlap feedback editor");J*d=cJSON_CreateObject();ss(d,"id","");ss(d,"title","");ss(d,"body","改善手机操作\n第二行内容");ss(d,"status","pending");char id[129];feedback_check(feedback_save(&a,d,id),"new opinion persists with generated title");feedback_check(!strcmp(str(feedback_get(&a,id),"title"),"改善手机操作"),"empty title derives first line");feedback_close(&a);feedback_check(feedback_open(&a,dir)&&feedback_get(&a,id),"opinions survive store restart");J*n=dup(feedback_get(&a,id));ss(n,"status","resolved");feedback_check(feedback_save(&a,n,id)&&!strcmp(str(feedback_get(&a,id),"status"),"resolved"),"edit status persists");J*before=dup(a.data),*incoming=dup(a.data);ss(cJSON_GetArrayItem(get(incoming,"ideas"),0),"body","较新版本");char stamp[40];feedback_stamp(stamp,str(feedback_get(&a,id),"updatedAt"));ss(cJSON_GetArrayItem(get(incoming,"ideas"),0),"updatedAt",stamp);int conflicts=0;feedback_check(feedback_import(&a,incoming,&conflicts)&&!strcmp(str(feedback_get(&a,id),"body"),"较新版本"),"newer import updates same opinion id");feedback_check(feedback_import(&a,before,&conflicts)&&!strcmp(str(feedback_get(&a,id),"body"),"较新版本"),"older import cannot overwrite newer version");J*conflict=dup(a.data);ss(cJSON_GetArrayItem(get(conflict,"ideas"),0),"body","同时间的独立内容");feedback_check(feedback_import(&a,conflict,&conflicts)&&conflicts==1&&cJSON_GetArraySize(get(a.data,"ideas"))==2,"same-time conflict keeps new-id copy");feedback_check(feedback_import(&a,conflict,&conflicts)&&!conflicts&&cJSON_GetArraySize(get(a.data,"ideas"))==2,"reimport does not duplicate conflict content");J*invalid=dup(a.data);ss(cJSON_GetArrayItem(get(invalid,"ideas"),0),"status","unknown");char*original=json(a.data);feedback_check(!feedback_import(&a,invalid,0),"invalid imported status rejected");char*actual=json(a.data);feedback_check(!strcmp(original,actual),"failed import leaves in-memory data unchanged");free(actual);char*disk=read_file(a.file);feedback_check(disk&&!strcmp(original,disk),"failed import leaves persisted data unchanged");free(disk);J*duplicate=dup(a.data);cJSON_AddItemToArray(get(duplicate,"ideas"),dup(cJSON_GetArrayItem(get(duplicate,"ideas"),0)));feedback_check(!feedback_import(&a,duplicate,0),"duplicate ids rejected atomically");J*badDate=dup(a.data);ss(cJSON_GetArrayItem(get(badDate,"ideas"),0),"createdAt","2026-02-30T10:00:00.000Z");feedback_check(!feedback_import(&a,badDate,0),"invalid calendar timestamp rejected");ss(d,"title","");ss(d,"body"," \t\r\n");feedback_check(!feedback_save(&a,d,0),"blank opinion not persisted");feedback_check(feedback_matches(feedback_get(&a,id),"较新 版本")&&!feedback_matches(feedback_get(&a,id),"较新 缺失"),"search matches all terms");wchar_t savedFile[32768];wcscpy(savedFile,a.file);wcscpy(a.file,a.dir);J*empty=feedback_empty();feedback_check(!feedback_write(&a,empty),"failed atomic replace is reported");cJSON_Delete(empty);wcscpy(a.file,savedFile);actual=json(a.data);feedback_check(!strcmp(original,actual),"failed atomic replace preserves memory");free(actual);disk=read_file(a.file);feedback_check(disk&&!strcmp(original,disk),"failed atomic replace preserves old file");free(disk);feedback_check(feedback_remove(&a,id)&&!feedback_get(&a,id),"delete persists independently of tasks");cJSON_Delete(before);cJSON_Delete(incoming);cJSON_Delete(conflict);cJSON_Delete(invalid);cJSON_Delete(duplicate);cJSON_Delete(badDate);cJSON_Delete(n);cJSON_Delete(d);free(original);feedback_close(&a);printf("{\"checks\":%d,\"failures\":%d}\n",feedback_test_checks,feedback_test_failures);return feedback_test_failures?1:0;}
